interface HookOutput {
  decision?: string;
  hookSpecificOutput?: {
    additionalContext?: string;
    permissionDecision?: string;
    permissionDecisionReason?: string;
  };
  reason?: string;
  systemMessage?: string;
}

interface RunHookOptions {
  args?: string[];
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  stdin?: string;
}

async function runHook(
  script: string,
  payload: unknown,
  options: RunHookOptions = {}
): Promise<{ code: number; stderr: string; stdout: string }> {
  return await new Promise((resolvePromise) => {
    const cliArgs = script.startsWith("supaschema hook ")
      ? [cliPath, ...script.split(" ").slice(1)]
      : [resolve(script), ...(options.args ?? [])];
    const child = execFile(
      process.execPath,
      cliArgs,
      { cwd: options.cwd, env: options.env },
      (error, stdout, stderr) => {
        const code = errorCode(error);
        resolvePromise({ code, stderr, stdout });
      }
    );
    child.stdin?.end(options.stdin ?? JSON.stringify(payload));
  });
}

async function runHookCommand(
  command: string,
  payload: unknown,
  options: { cwd: string; env: NodeJS.ProcessEnv }
): Promise<{ code: number; stderr: string; stdout: string }> {
  return await new Promise((resolvePromise) => {
    const child = exec(command, options, (error, stdout, stderr) => {
      resolvePromise({ code: errorCode(error), stderr, stdout });
    });
    child.stdin?.end(JSON.stringify(payload));
  });
}

function errorCode(error: unknown): number {
  if (!isRecord(error)) {
    return 0;
  }
  return typeof error.code === "number" ? error.code : 1;
}

function hookAdditionalContext(stdout: string): string {
  const output = hookOutput(stdout);
  return output.hookSpecificOutput?.additionalContext ?? "";
}

function hookOutput(stdout: string): HookOutput {
  const parsed = jsonRecord(stdout);
  const rawHookOutput = isRecord(parsed.hookSpecificOutput) ? parsed.hookSpecificOutput : {};
  return {
    decision: stringValue(parsed.decision),
    hookSpecificOutput: {
      additionalContext: stringValue(rawHookOutput.additionalContext),
      permissionDecision: stringValue(rawHookOutput.permissionDecision),
      permissionDecisionReason: stringValue(rawHookOutput.permissionDecisionReason),
    },
    reason: stringValue(parsed.reason),
    systemMessage: stringValue(parsed.systemMessage),
  };
}

function jsonRecord(text: string): Record<string, unknown> {
  const parsed: unknown = text.trim().length > 0 ? JSON.parse(text) : {};
  return isRecord(parsed) ? parsed : {};
}

function jsonStringArray(text: string): string[] {
  const parsed: unknown = JSON.parse(text);
  return Array.isArray(parsed) ? parsed.filter((item) => typeof item === "string") : [];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stringValue(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

