async function readFakeCalls(log: string): Promise<string[][]> {
  const content = await readFile(log, "utf8").catch((error: unknown) => {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return "";
    }
    throw error;
  });
  return content.trim().split("\n").filter(Boolean).map(jsonStringArray);
}

function hookJson(stdout: string): Record<string, unknown> {
  return jsonRecord(stdout);
}

function hookHandlers(value: unknown): Record<string, unknown>[] {
  const out: Record<string, unknown>[] = [];
  const visit = (candidate: unknown) => {
    if (Array.isArray(candidate)) {
      for (const item of candidate) {
        visit(item);
      }
      return;
    }
    if (!(candidate && typeof candidate === "object")) {
      return;
    }
    if (typeof candidate.command === "string" && candidate.type === "command") {
      out.push(candidate);
    }
    for (const item of Object.values(candidate)) {
      visit(item);
    }
  };
  visit(value);
  return out;
}

function hookEntries(
  config: Record<string, unknown>,
  eventName: string
): Record<string, unknown>[] {
  if (!isRecord(config.hooks)) {
    return [];
  }
  const entries = config.hooks[eventName];
  return Array.isArray(entries) ? entries.filter(isRecord) : [];
}

function codexPreToolUseCommandsFor(config: Record<string, unknown>, toolName: string): string[] {
  return hookEntries(config, "PreToolUse")
    .filter((entry) => matcherMentionsTool(entry.matcher, toolName))
    .flatMap((entry) =>
      hookHandlers(entry)
        .map((handler) => handler.command)
        .filter((command): command is string => typeof command === "string")
    );
}

function claudePreToolUseCommandsFor(config: Record<string, unknown>, toolName: string): string[] {
  return hookEntries(config, "PreToolUse")
    .filter((entry) => claudeMatcherMentionsTool(entry.matcher, toolName))
    .flatMap((entry) => hookHandlers(entry).map(handlerCommandText));
}

function claudeMatcherMentionsTool(matcher: unknown, toolName: string): boolean {
  if (typeof matcher !== "string" || matcher.length === 0) {
    return true;
  }
  return hookMatcherMatchesTool(matcher, toolName);
}

function handlerCommandText(handler: Record<string, unknown>): string {
  return [
    typeof handler.command === "string" ? handler.command : "",
    ...(Array.isArray(handler.args)
      ? handler.args.filter((arg): arg is string => typeof arg === "string")
      : []),
  ]
    .filter(Boolean)
    .join(" ");
}

function matcherMentionsTool(matcher: unknown, toolName: string): boolean {
  if (typeof matcher !== "string") {
    return false;
  }
  return hookMatcherMatchesTool(matcher, toolName);
}

function workspaceVariable(name: string): string {
  return ["$", "{", name, "}"].join("");
}

function withoutCodexProjectDir(env: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  return Object.fromEntries(Object.entries(env).filter(([name]) => name !== "CODEX_PROJECT_DIR"));
}

function codexSessionStartPayload(source: string, sessionId: string): Record<string, unknown> {
  return {
    cwd: process.cwd(),
    hook_event_name: "SessionStart",
    model: "test-model",
    permission_mode: "default",
    session_id: sessionId,
    source,
    transcript_path: null,
  };
}

function codexWindowsProbePayload(
  eventName: string,
  cwd: string,
  sessionId: string
): Record<string, unknown> {
  const common = {
    cwd,
    hook_event_name: eventName,
    model: "test-model",
    permission_mode: "default",
    session_id: sessionId,
    transcript_path: null,
  };
  if (eventName === "SessionStart") {
    return { ...common, source: "startup" };
  }
  if (eventName === "UserPromptSubmit") {
    return { ...common, prompt: "Native Windows hook entrypoint probe." };
  }
  if (eventName === "PreToolUse" || eventName === "PostToolUse") {
    return {
      ...common,
      tool_input: {
        command: "*** Begin Patch\n*** Add File: windows-hook-probe.txt\n+probe\n*** End Patch\n",
      },
      tool_name: "apply_patch",
      ...(eventName === "PostToolUse" ? { tool_response: { exit_code: 0 } } : {}),
    };
  }
  if (eventName === "SubagentStart") {
    return { ...common, agent_id: "windows-probe-agent", agent_type: "worker" };
  }
  if (eventName === "SubagentStop") {
    return {
      ...common,
      agent_id: "windows-probe-agent",
      last_assistant_message: "Windows hook probe finished.",
      stop_hook_active: false,
    };
  }
  if (eventName === "Stop") {
    return {
      ...common,
      last_assistant_message: "Windows hook probe response.",
      stop_hook_active: false,
    };
  }
  return { ...common, reason: "other" };
}

async function sessionState(stateDir: string): Promise<Record<string, unknown>> {
  const files = (await readdir(stateDir)).filter((file) => file.endsWith(".json"));
  expect(files).toHaveLength(1);
  return jsonRecord(await readFile(join(stateDir, files[0]), "utf8"));
}

