    "git merge --squash feature/demo",
    "git reset --hard",
    'git commit --no-verify -m "skip"',
    "git push origin main",
    "git push origin HEAD:main",
    "git push origin HEAD:refs/heads/main",
    "git push origin HEAD",
    "git push origin +main",
    "git push origin +refs/heads/main",
    "git push origin +HEAD:main",
    "git push",
    "git push origin",
